class Solution {
public:
    string solveEquation(string equation) {
        auto parse = [](const string& side) -> pair<int, int> {
            int coeff = 0, constVal = 0, sign = 1, i = 0, n = side.size();
            while (i < n) {
                if (side[i] == '+') {
                    sign = 1;
                    i++;
                } else if (side[i] == '-') {
                    sign = -1;
                    i++;
                }
                int j = i;
                while (j < n && (isdigit(side[j]) || side[j] == 'x')) j++;
                string token = side.substr(i, j - i);
                i = j;
                if (token.empty()) continue;
                if (token.back() == 'x') {
                    string num = token.substr(0, token.size() - 1);
                    int val = num.empty() ? 1 : stoi(num);
                    coeff += sign * val;
                } else {
                    constVal += sign * stoi(token);
                }
            }
            return {coeff, constVal};
        };
        size_t eq = equation.find('=');
        auto [c1, k1] = parse(equation.substr(0, eq));
        auto [c2, k2] = parse(equation.substr(eq + 1));
        int coeff = c1 - c2;
        int constVal = k2 - k1;
        if (coeff == 0) {
            return constVal == 0 ? "Infinite solutions" : "No solution";
        }
        return "x=" + to_string(constVal / coeff);
    }
};

class Solution {
    public String solveEquation(String equation) {
        String[] sides = equation.split("=");
        int[] left = parse(sides[0]);
        int[] right = parse(sides[1]);
        int coeff = left[0] - right[0];
        int constVal = right[1] - left[1];
        if (coeff == 0) {
            return constVal == 0 ? "Infinite solutions" : "No solution";
        }
        return "x=" + (constVal / coeff);
    }

    private int[] parse(String side) {
        int coeff = 0, constVal = 0, sign = 1, i = 0, n = side.length();
        while (i < n) {
            if (side.charAt(i) == '+') {
                sign = 1;
                i++;
            } else if (side.charAt(i) == '-') {
                sign = -1;
                i++;
            }
            int j = i;
            while (j < n && (Character.isDigit(side.charAt(j)) || side.charAt(j) == 'x')) {
                j++;
            }
            String token = side.substring(i, j);
            i = j;
            if (token.isEmpty()) continue;
            if (token.endsWith("x")) {
                String num = token.substring(0, token.length() - 1);
                int val = num.isEmpty() ? 1 : Integer.parseInt(num);
                coeff += sign * val;
            } else {
                constVal += sign * Integer.parseInt(token);
            }
        }
        return new int[]{coeff, constVal};
    }
}

