var solveEquation = function(equation) {
    function parse(side) {
        let coeff = 0, constVal = 0, sign = 1, i = 0, n = side.length;
        while (i < n) {
            if (side[i] === '+') {
                sign = 1;
                i++;
            } else if (side[i] === '-') {
                sign = -1;
                i++;
            }
            let j = i;
            while (j < n && ((side[j] >= '0' && side[j] <= '9') || side[j] === 'x')) {
                j++;
            }
            const token = side.slice(i, j);
            i = j;
            if (!token) continue;
            if (token.endsWith('x')) {
                const num = token.slice(0, -1);
                const val = num === '' ? 1 : parseInt(num, 10);
                coeff += sign * val;
            } else {
                constVal += sign * parseInt(token, 10);
            }
        }
        return [coeff, constVal];
    }
    const [left, right] = equation.split('=');
    const [c1, k1] = parse(left);
    const [c2, k2] = parse(right);
    const coeff = c1 - c2;
    const constVal = k2 - k1;
    if (coeff === 0) {
        return constVal === 0 ? "Infinite solutions" : "No solution";
    }
    return `x=${Math.trunc(constVal / coeff)}`;
};
